   122→- [ ] **Step 3: Implement compilePattern**
   123→
   124→```typescript
   125→// apps/desktop/src/navigation/route-compiler.ts
   126→
   127→export interface CompiledPattern {
   128→  pattern: string;
   129→  regex: RegExp;
   130→  paramNames: string[];
   131→  restParam: string | null;
   132→  build: (params: Record<string, string>) => string;
   133→  constantSegmentCount: number;
   134→}
   135→
   136→/**
   137→ * Compile a URL pattern into a regex matcher and URL builder.
   138→ * Patterns use :param for single segments and :param+ for rest (multi-segment).
   139→ * All compiled regexes are anchored with ^ and $.
   140→ */
   141→export function compilePattern(pattern: string): CompiledPattern {
   142→  const paramNames: string[] = [];
   143→  let restParam: string | null = null;
   144→  let constantSegmentCount = 0;
   145→
   146→  const segments = pattern.split("/").filter(Boolean);
   147→  const regexParts: string[] = [];
   148→  const buildParts: Array<{ type: "const"; value: string } | { type: "param"; name: string; rest: boolean }> = [];
   149→
   150→  for (const segment of segments) {
   151→    if (segment.startsWith(":")) {
   152→      const isRest = segment.endsWith("+");
   153→      const name = isRest ? segment.slice(1, -1) : segment.slice(1);
   154→      paramNames.push(name);
   155→      if (isRest) {
   156→        restParam = name;
   157→        regexParts.push("(.+)");
   158→      } else {
   159→        regexParts.push("([^/]+)");
   160→      }
   161→      buildParts.push({ type: "param", name, rest: isRest });
   162→    } else {
   163→      constantSegmentCount++;
   164→      regexParts.push(escapeRegex(segment));
   165→      buildParts.push({ type: "const", value: segment });
   166→    }
   167→  }
   168→
   169→  const regex = new RegExp("^\\/" + regexParts.join("\\/") + "$");
   170→
   171→  const build = (params: Record<string, string>): string => {
   172→    const parts = buildParts.map((part) => {
   173→      if (part.type === "const") return part.value;
   174→      const value = params[part.name];
   175→      if (!value && part.rest) {
   176→        throw new Error(`Rest param "${part.name}" must be non-empty for pattern: ${pattern}`);
   177→      }
   178→      // Rest params: keep / unencoded. Single params: encode.
   179→      return part.rest ? value : encodeURIComponent(value);
   180→    });
   181→    return "/" + parts.join("/");
   182→  };
   183→
   184→  return { pattern, regex, paramNames, restParam, build, constantSegmentCount };
   185→}
   186→
   187→function escapeRegex(str: string): string {
   188→  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
   189→}
   190→```
