   280→- [ ] **Step 6: Implement matchUrl and buildUrl + RouteEntry type**
   281→
   282→Add to `route-compiler.ts`:
   283→
   284→```typescript
   285→import type { IconData } from "@/components/ui/icon-picker";
   286→
   287→export interface RouteEntry<TParams extends Record<string, string> = Record<string, string>> {
   288→  pattern: string;
   289→  icon: IconData | ((params: TParams) => IconData);
   290→  title: string | ((params: TParams) => string);
   291→  titleKey?: string;
   292→  isContainer?: boolean;
   293→  queryParams?: string[];
   294→  dropdownCategory?: string;
   295→}
   296→
   297→export interface RouteMatch {
   298→  pattern: string;
   299→  params: Record<string, string>;
   300→  icon: IconData;
   301→  title: string;
   302→  entry: RouteEntry;
   303→}
   304→
   305→export interface CompiledRoute extends CompiledPattern {
   306→  entry: RouteEntry;
   307→  queryParams: string[];
   308→}
   309→
   310→/** Compile all entries, sorted by specificity (more constant segments first, no-rest before rest) */
   311→export function compileRegistry(entries: RouteEntry[]): CompiledRoute[] {
   312→  const compiled = entries.map((entry) => ({
   313→    ...compilePattern(entry.pattern),
   314→    entry,
   315→    queryParams: entry.queryParams ?? [],
   316→  }));
   317→
   318→  // Sort: more constant segments first; tie-break: no rest before rest
   319→  compiled.sort((a, b) => {
   320→    if (b.constantSegmentCount !== a.constantSegmentCount) {
   321→      return b.constantSegmentCount - a.constantSegmentCount;
   322→    }
   323→    return (a.restParam ? 1 : 0) - (b.restParam ? 1 : 0);
   324→  });
   325→
   326→  return compiled;
   327→}
   328→
   329→export function matchUrl(url: string, entries: RouteEntry[]): RouteMatch | null {
   330→  const compiled = compileRegistry(entries);
   331→  return matchUrlCompiled(url, compiled);
   332→}
   333→
   334→export function matchUrlCompiled(url: string, compiled: CompiledRoute[]): RouteMatch | null {
   335→  const parsed = new URL(url, "http://localhost");
   336→  const pathname = parsed.pathname;
   337→
   338→  for (const route of compiled) {
   339→    const pathMatch = route.regex.exec(pathname);
   340→    if (!pathMatch) continue;
   341→
   342→    const params: Record<string, string> = {};
   343→    route.paramNames.forEach((name, i) => {
   344→      const raw = pathMatch[i + 1];
   345→      // Rest params: decode each segment individually to preserve "/" as path separator
   346→      // Single params: decode the whole value
   347→      params[name] = name === route.restParam
   348→        ? raw.split("/").map(decodeURIComponent).join("/")
   349→        : decodeURIComponent(raw);
   350→    });
   351→
   352→    for (const qp of route.queryParams) {
   353→      const value = parsed.searchParams.get(qp);
   354→      if (value) params[qp] = value;
   355→    }
   356→
   357→    return {
   358→      pattern: route.pattern,
   359→      params,
   360→      icon: resolveIcon(route.entry, params),
   361→      title: resolveTitle(route.entry, params),
   362→      entry: route.entry,
   363→    };
   364→  }
   365→  return null;
   366→}
   367→
   368→export function buildUrl(pattern: string, params: Record<string, string>, entries: RouteEntry[]): string {
   369→  const compiled = compileRegistry(entries);
   370→  return buildUrlCompiled(pattern, params, compiled);
   371→}
   372→
   373→export function buildUrlCompiled(pattern: string, params: Record<string, string>, compiled: CompiledRoute[]): string {
   374→  const route = compiled.find((r) => r.pattern === pattern);
   375→  if (!route) throw new Error(`Unknown pattern: ${pattern}`);
   376→
   377→  let path = route.build(params);
   378→
   379→  const queryEntries = route.queryParams
   380→    .filter((qp) => params[qp])
   381→    .map((qp) => [qp, params[qp]] as [string, string]);
   382→
   383→  if (queryEntries.length > 0) {
   384→    path += "?" + new URLSearchParams(queryEntries).toString();
   385→  }
   386→
   387→  return path;
   388→}
   389→
   390→function resolveIcon(entry: RouteEntry, params: Record<string, string>): IconData {
   391→  return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   392→}
   393→
   394→function resolveTitle(entry: RouteEntry, params: Record<string, string>): string {
   395→  return typeof entry.title === "function" ? entry.title(params) : entry.title;
   396→}
   397→```
