   510→    return compiledByPattern.has(pattern);
   511→  },
   512→
   513→  getRestParam(pattern: string): string | null {
   514→    return compiledByPattern.get(pattern)?.restParam ?? null;
   515→  },
   516→
   517→  getParamNames(pattern: string): string[] {
   518→    return compiledByPattern.get(pattern)?.paramNames ?? [];
   519→  },
   520→
   521→  getByCategory(category: string): RouteEntry[] {
   522→    return compiled.filter((r) => r.entry.dropdownCategory === category).map((r) => r.entry);
   523→  },
   524→
   525→  getIcon(pattern: string, params: Record<string, string> = {}): IconData | undefined {
   526→    const entry = compiledByPattern.get(pattern)?.entry;
   527→    if (!entry) return undefined;
   528→    return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   529→  },
   530→
   531→  normalizeUrl(url: string): string {
   532→    const match = this.match(url);
   533→    if (!match) {
   534→      const { pathname } = new URL(url, "http://localhost");
   535→      return pathname;
   536→    }
   537→    return this.build(match.pattern, match.params);
   538→  },
   539→};
