   674→// apps/desktop/src/navigation/breadcrumb-builder.ts
   675→import { registry, humanize } from "./route-registry";
   676→import type { RouteEntry, RouteMatch } from "./route-compiler";
   677→import type { IconData } from "@/components/ui/icon-picker";
   678→
   679→// ─── Types ──────────────────────────────────────────────────────────────────
   680→
   681→export interface NavigateHeaders {
   682→  label?: string;
   683→  icon?: IconData;
   684→  id?: string;
   685→  sourceNodeId?: string;
   686→  parentNodeId?: string;
   687→  meta?: BreadcrumbMeta;
   688→}
   689→
   690→export interface BreadcrumbMeta {
   691→  workspaceId?: string;
   692→  section?: string;
   693→  pageSlug?: string;
   694→  agentId?: string;
   695→  executorType?: string;
   696→  webId?: string;
   697→  url?: string;
   698→  blockId?: string;
   699→}
   700→
   701→export interface BreadcrumbStackItem {
   702→  id: string;
   703→  label: string;
   704→  icon?: IconData;
   705→  pattern?: string;
   706→  href?: string;
   707→  sourceNodeId?: string;
   708→  parentNodeId?: string;
   709→  meta?: BreadcrumbMeta;
   710→}
   711→
   712→// ─── Cold Start Builder ─────────────────────────────────────────────────────
   713→
   714→export function buildColdStartBreadcrumb(url: string, headers?: NavigateHeaders): BreadcrumbStackItem[] {
   715→  const match = registry.match(url);
   716→  if (!match) return [];
   717→
   718→  const chain: BreadcrumbStackItem[] = [];
   719→
   720→  // 1. Path prefix ancestors
   721→  for (const ancestorPattern of deriveAncestorsFromPrefix(match.pattern)) {
   722→    const ancestorEntry = registry.getEntry(ancestorPattern)!;
   723→    const ancestorParams = pickMatchingParams(ancestorPattern, match.params);
   724→    chain.push(buildBreadcrumbItem(ancestorEntry, ancestorParams));
   725→  }
   726→
   727→  // 2. Rest param intermediate levels
   728→  const restParam = registry.getRestParam(match.pattern);
   729→  if (restParam && match.params[restParam]?.includes("/")) {
   730→    const segments = match.params[restParam].split("/");
   731→    for (let i = 1; i < segments.length; i++) {
   732→      const prefix = segments.slice(0, i).join("/");
   733→      const lastSegment = segments[i - 1];
   734→      chain.push(buildBreadcrumbItem(
   735→        match.entry,
   736→        { ...match.params, [restParam]: prefix },
   737→        { label: humanize(lastSegment) },
   738→      ));
   739→    }
   740→  }
   741→
   742→  // 3. Current node (headers can override label/icon)
   743→  chain.push(buildBreadcrumbItem(match.entry, match.params, headers));
   744→
   745→  return chain;
   746→}
   747→
   748→// ─── Helpers ────────────────────────────────────────────────────────────────
   749→
   750→export function deriveAncestorsFromPrefix(pattern: string): string[] {
   751→  const segments = pattern.split("/").filter(Boolean);
   752→  const ancestors: string[] = [];
   753→
   754→  for (let i = segments.length - 1; i > 0; i--) {
   755→    const candidate = "/" + segments.slice(0, i).join("/");
   756→    if (registry.hasEntry(candidate)) {
   757→      ancestors.unshift(candidate);
   758→    }
   759→  }
   760→  return ancestors;
   761→}
   762→
   763→export function pickMatchingParams(
   764→  targetPattern: string,
   765→  allParams: Record<string, string>,
   766→): Record<string, string> {
   767→  const paramNames = registry.getParamNames(targetPattern);
   768→  const result: Record<string, string> = {};
   769→  for (const name of paramNames) {
   770→    if (allParams[name] !== undefined) {
   771→      result[name] = allParams[name];
   772→    }
   773→  }
   774→  return result;
   775→}
   776→
   777→export function buildBreadcrumbItem(
   778→  entry: RouteEntry,
   779→  params: Record<string, string>,
   780→  headers?: NavigateHeaders,
   781→): BreadcrumbStackItem {
   782→  const href = registry.build(entry.pattern, params);
   783→  const icon = headers?.icon ?? (typeof entry.icon === "function" ? entry.icon(params) : entry.icon);
   784→  const title = typeof entry.title === "function" ? entry.title(params) : entry.title;
   785→
   786→  return {
   787→    id: headers?.id ?? href,
   788→    label: headers?.label ?? title,
   789→    icon,
   790→    pattern: entry.pattern,
   791→    href,
   792→    sourceNodeId: headers?.sourceNodeId,
   793→    parentNodeId: headers?.parentNodeId,
   794→    meta: headers?.meta,
   795→  };
   796→}
   797→```
