  1133→Key implementation:
  1134→
  1135→```typescript
  1136→import { registry, buildColdStartBreadcrumb, buildBreadcrumbItem, isStackPrefixOf } from "@/navigation/navigate";
  1137→import { useTabStore } from "@/stores/tab-store";
  1138→import { useLocation, useNavigate as useRouterNavigate } from "react-router-dom";
