  1140→// syncRouterToStore logic:
  1141→const match = registry.match(normalizedUrl);
  1142→if (!match) {
  1143→  // Unknown URL — don't update tab store, let React Router handle it
  1144→  syncLockRef.current = false;
  1145→  return;
  1146→}
  1147→if (isStackPrefixOf(currentState.breadcrumbStack, match)) {
