    78→export function deriveAncestorsFromPrefix(pattern: string): string[] {
    79→  const segments = pattern.split("/").filter(Boolean);
    80→  const ancestors: string[] = [];
    81→
    82→  for (let i = segments.length - 1; i > 0; i--) {
    83→    const candidate = "/" + segments.slice(0, i).join("/");
    84→    if (registry.hasEntry(candidate)) {
    85→      ancestors.unshift(candidate);
