     1→/**
     2→ * Route Compiler — Core Engine
     3→ *
     4→ * Pure functions for compiling URL patterns, matching URLs against a registry,
     5→ * and building URLs from patterns + params.
     6→ *
     7→ * Pattern syntax:
     8→ *   /workspace/:workspaceId        — named param (matches one segment)
     9→ *   /workspace/:workspaceId/pages/:pageSlug+  — rest param (matches 1+ segments)
    10→ */
    11→
    12→import type { IconData } from "@/components/ui/icon-picker";
    13→
    14→// ─── Types ───────────────────────────────────────────────────────────────────
    15→
    16→export interface CompiledPattern {
    17→  pattern: string;
    18→  regex: RegExp;
    19→  paramNames: string[];
    20→  restParam: string | null;
    21→  build: (params: Record<string, string>) => string;
    22→  constantSegmentCount: number;
    23→}
    24→
    25→export interface RouteEntry<TParams extends Record<string, string> = Record<string, string>> {
    26→  pattern: string;
    27→  icon: IconData | ((params: TParams) => IconData);
    28→  title: string | ((params: TParams) => string);
    29→  titleKey?: string;
    30→  isContainer?: boolean;
    31→  queryParams?: string[];
    32→  dropdownCategory?: string;
    33→}
    34→
    35→export interface RouteMatch {
    36→  pattern: string;
    37→  params: Record<string, string>;
    38→  icon: IconData;
    39→  title: string;
    40→  entry: RouteEntry;
    41→}
    42→
    43→export interface CompiledRoute extends CompiledPattern {
    44→  entry: RouteEntry;
    45→  queryParams: string[];
    46→}
    47→
    48→// ─── Core: compilePattern ────────────────────────────────────────────────────
    49→
    50→export function compilePattern(pattern: string): CompiledPattern {
    51→  const paramNames: string[] = [];
    52→  let restParam: string | null = null;
    53→  let constantSegmentCount = 0;
    54→
    55→  const segments = pattern.split("/").filter(Boolean);
    56→  const regexParts: string[] = [];
    57→  const buildParts: Array<
    58→    | { type: "const"; value: string }
    59→    | { type: "param"; name: string; rest: boolean }
    60→  > = [];
    61→
    62→  for (const segment of segments) {
    63→    if (segment.startsWith(":")) {
    64→      const isRest = segment.endsWith("+");
    65→      const name = isRest ? segment.slice(1, -1) : segment.slice(1);
    66→      paramNames.push(name);
    67→      if (isRest) {
    68→        restParam = name;
    69→        regexParts.push("(.+)");
    70→      } else {
    71→        regexParts.push("([^/]+)");
    72→      }
    73→      buildParts.push({ type: "param", name, rest: isRest });
    74→    } else {
    75→      constantSegmentCount++;
    76→      regexParts.push(escapeRegex(segment));
    77→      buildParts.push({ type: "const", value: segment });
    78→    }
    79→  }
    80→
    81→  const regex = new RegExp("^\\/" + regexParts.join("\\/") + "$");
    82→
    83→  const build = (params: Record<string, string>): string => {
    84→    const parts = buildParts.map((part) => {
    85→      if (part.type === "const") return part.value;
    86→      const value = params[part.name];
    87→      if (!value) {
    88→        throw new Error(`Param "${part.name}" must be non-empty for pattern: ${pattern}`);
    89→      }
    90→      return part.rest ? value : encodeURIComponent(value);
    91→    });
    92→    return "/" + parts.join("/");
    93→  };
    94→
    95→  return { pattern, regex, paramNames, restParam, build, constantSegmentCount };
    96→}
    97→
    98→// ─── Registry ────────────────────────────────────────────────────────────────
    99→
   100→export function compileRegistry(entries: RouteEntry[]): CompiledRoute[] {
   101→  const compiled = entries.map((entry) => ({
   102→    ...compilePattern(entry.pattern),
   103→    entry,
   104→    queryParams: entry.queryParams ?? [],
   105→  }));
   106→
   107→  // Sort: more constant segments first, then non-rest before rest
   108→  compiled.sort((a, b) => {
   109→    if (b.constantSegmentCount !== a.constantSegmentCount) {
   110→      return b.constantSegmentCount - a.constantSegmentCount;
   111→    }
   112→    return (a.restParam ? 1 : 0) - (b.restParam ? 1 : 0);
   113→  });
   114→
   115→  // Dev-time conflict detection: verify no two patterns match the same sample URL
   116→  if (process.env.NODE_ENV !== "production") {
   117→    for (let i = 0; i < compiled.length; i++) {
   118→      for (let j = i + 1; j < compiled.length; j++) {
   119→        const a = compiled[i];
   120→        const b = compiled[j];
   121→        const sampleA = a.build(generateSampleParams(a));
   122→        if (b.regex.test(sampleA)) {
   123→          console.warn(
   124→            `[route-registry] Potential conflict: "${a.pattern}" sample URL "${sampleA}" also matches "${b.pattern}"`
   125→          );
   126→        }
   127→      }
   128→    }
   129→  }
   130→
   131→  return compiled;
   132→}
   133→
   134→function generateSampleParams(route: CompiledRoute): Record<string, string> {
   135→  const params: Record<string, string> = {};
   136→  for (const name of route.paramNames) {
   137→    params[name] = `sample-${name}`;
   138→  }
   139→  return params;
   140→}
   141→
   142→// ─── matchUrl ────────────────────────────────────────────────────────────────
   143→
   144→export function matchUrl(url: string, entries: RouteEntry[]): RouteMatch | null {
   145→  const compiled = compileRegistry(entries);
   146→  return matchUrlCompiled(url, compiled);
   147→}
   148→
   149→export function matchUrlCompiled(url: string, compiled: CompiledRoute[]): RouteMatch | null {
   150→  const parsed = new URL(url, "http://localhost");
   151→  const pathname = parsed.pathname;
   152→
   153→  for (const route of compiled) {
   154→    const pathMatch = route.regex.exec(pathname);
   155→    if (!pathMatch) continue;
   156→
   157→    const params: Record<string, string> = {};
   158→    route.paramNames.forEach((name, i) => {
   159→      const raw = pathMatch[i + 1];
   160→      params[name] =
   161→        name === route.restParam
   162→          ? raw.split("/").map(decodeURIComponent).join("/")
   163→          : decodeURIComponent(raw);
   164→    });
   165→
   166→    // Extract declared query params
   167→    for (const qp of route.queryParams) {
   168→      const value = parsed.searchParams.get(qp);
   169→      if (value) params[qp] = value;
   170→    }
   171→
   172→    return {
   173→      pattern: route.pattern,
   174→      params,
   175→      icon: resolveIcon(route.entry, params),
   176→      title: resolveTitle(route.entry, params),
   177→      entry: route.entry,
   178→    };
   179→  }
   180→  return null;
   181→}
   182→
   183→// ─── buildUrl ────────────────────────────────────────────────────────────────
   184→
   185→export function buildUrl(
   186→  pattern: string,
   187→  params: Record<string, string>,
   188→  entries: RouteEntry[],
   189→): string {
   190→  const compiled = compileRegistry(entries);
   191→  return buildUrlCompiled(pattern, params, compiled);
   192→}
   193→
   194→export function buildUrlCompiled(
   195→  pattern: string,
   196→  params: Record<string, string>,
   197→  compiled: CompiledRoute[],
   198→): string {
   199→  const route = compiled.find((r) => r.pattern === pattern);
   200→  if (!route) throw new Error(`Unknown pattern: ${pattern}`);
   201→
   202→  let path = route.build(params);
   203→
   204→  const queryEntries = route.queryParams
   205→    .filter((qp) => params[qp])
   206→    .map((qp) => [qp, params[qp]] as [string, string]);
   207→
   208→  if (queryEntries.length > 0) {
   209→    path += "?" + new URLSearchParams(queryEntries).toString();
   210→  }
   211→
   212→  return path;
   213→}
   214→
   215→// ─── Helpers ─────────────────────────────────────────────────────────────────
   216→
   217→function resolveIcon(entry: RouteEntry, params: Record<string, string>): IconData {
   218→  return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   219→}
   220→
   221→function resolveTitle(entry: RouteEntry, params: Record<string, string>): string {
   222→  return typeof entry.title === "function" ? entry.title(params) : entry.title;
   223→}
   224→
   225→function escapeRegex(str: string): string {
   226→  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
   227→}
