     1→import { useEffect, useRef } from "react";
     2→import { useLocation, useNavigate as useRouterNavigate } from "react-router-dom";
     3→import { registry } from "@/navigation/route-registry";
     4→import { buildColdStartBreadcrumb, buildBreadcrumbItem } from "@/navigation/breadcrumb-builder";
     5→import { isStackPrefixOf } from "@/navigation/navigate";
     6→import { useTabStore, selectActiveTab } from "@/stores/tab-store";
     7→
     8→/**
     9→ * Tab-Router Bridge
    10→ *
    11→ * Bidirectional sync between the tab store's navigation state and React Router.
    12→ * Uses a sync lock to prevent infinite loops.
    13→ */
    14→export function TabRouterBridge() {
    15→  const routerNavigate = useRouterNavigate();
    16→  const location = useLocation();
    17→  const syncLockRef = useRef(false);
    18→
    19→  // Get the active tab's current URL from the store
    20→  const activeTab = useTabStore(selectActiveTab);
    21→  const activeTabId = useTabStore((s) => s.activeTabId);
    22→  const storeUrl = activeTab?.navigationHistory[activeTab.historyIndex]?.url ?? null;
    23→
    24→  // Store actions
    25→  const pushNavigation = useTabStore((s) => s.pushNavigation);
    26→  const resetNavigation = useTabStore((s) => s.resetNavigation);
    27→
    28→  // Store -> Router: when store URL changes, update React Router
    29→  useEffect(() => {
    30→    if (!storeUrl) return;
    31→
    32→    const currentRouterPath = location.pathname + location.search;
    33→    const normalizedStoreUrl = registry.normalizeUrl(storeUrl);
    34→
    35→    if (normalizedStoreUrl === currentRouterPath) return;
    36→
    37→    // Set sync lock to prevent Router->Store from triggering
    38→    syncLockRef.current = true;
    39→    routerNavigate(normalizedStoreUrl, { replace: true });
    40→
    41→    // Release lock after React Router processes the navigation
    42→    requestAnimationFrame(() => {
    43→      syncLockRef.current = false;
    44→    });
    45→  }, [storeUrl, routerNavigate, location.pathname, location.search]);
    46→
    47→  // Router -> Store: when React Router URL changes externally, update store
    48→  useEffect(() => {
    49→    // Skip if we caused this navigation (sync lock active)
    50→    if (syncLockRef.current) return;
    51→    if (!activeTabId) return;
    52→
    53→    const currentRouterUrl = location.pathname + location.search;
    54→    const normalizedUrl = registry.normalizeUrl(currentRouterUrl);
    55→
    56→    // Skip if URLs already match
    57→    if (storeUrl && registry.normalizeUrl(storeUrl) === normalizedUrl) return;
    58→
    59→    // Match against registry
    60→    const match = registry.match(normalizedUrl);
    61→    if (!match) {
    62→      // Unknown URL — don't update tab store, let React Router handle it
    63→      return;
    64→    }
    65→
    66→    // Get current breadcrumb stack from active tab
    67→    const currentState = activeTab?.navigationHistory[activeTab.historyIndex];
    68→    const currentStack = currentState?.breadcrumbStack ?? [];
    69→
    70→    if (isStackPrefixOf(currentStack, match)) {
    71→      // Smart push: existing stack is valid ancestor chain
    72→      const leaf = buildBreadcrumbItem(match.entry, match.params);
    73→      pushNavigation(activeTabId, normalizedUrl, leaf);
    74→    } else {
    75→      // Cold-start reset: deep link or direct URL entry
    76→      const stack = buildColdStartBreadcrumb(normalizedUrl);
    77→      resetNavigation(activeTabId, normalizedUrl, stack);
    78→    }
    79→  }, [location.pathname, location.search]);
    80→
    81→  return null;
    82→}
