   176→function safeHostname(url: string): string {
   177→  try {
   178→    return new URL(url).hostname;
   179→  } catch {
   180→    return url;
   181→  }
   182→}
   183→
   184→function inferWorkspaceIdFromUrl(url: string | null): string | null {
   185→  if (!url) return null;
   186→  const match = registry.match(url);
   187→  return match?.params?.workspaceId ?? null;
   188→}
   189→
   190→function buildTabStoreActions(activeTabId: string | null) {
   191→  const store = useTabStore.getState();
   192→  return {
   193→    activeTabId: activeTabId ?? "",
   194→    pushNavigation: store.pushNavigation,
   195→    replaceNavigation: store.replaceNavigation,
   196→    resetNavigation: store.resetNavigation,
   197→  };
   198→}
