   155→export function mergePersistedTabState(
   156→  persisted: Partial<TabState> | undefined,
   157→  current: TabState
   158→): TabState {
   159→  const tabs = (persisted?.tabs ?? []).filter(isPersistedPageTab).map(normalizeTab);
   160→  const tabIds = new Set(tabs.map((tab) => tab.id));
   161→  const activeTabId =
   162→    persisted?.activeTabId && tabIds.has(persisted.activeTabId)
   163→      ? persisted.activeTabId
   164→      : tabs[0]?.id ?? null;
   165→
   166→  return {
   167→    ...current,
   168→    tabs,
   169→    activeTabId,
   170→    recentlyClosedTabs: (persisted?.recentlyClosedTabs ?? [])
   171→      .filter(isPersistedSnapshot)
   172→      .map(normalizeSnapshot),
   173→  };
   174→}
   175→
   176→function cloneTabWithNewId(tab: PageTab, overrides?: Partial<PageTab>): PageTab {
   177→  return normalizeTab({
   178→    ...normalizeTab(tab),
   179→    ...overrides,
   180→    id: generateTabId(),
   181→  });
   182→}
   183→
   184→function createClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
   185→  return {
   186→    tab: normalizeTab(tab),
   187→    originIndex,
   188→    closedAt: Date.now(),
   189→  };
   190→}
   191→
   192→function pushClosedSnapshots(
   193→  stack: ClosedTabSnapshot[],
   194→  snapshots: ClosedTabSnapshot[]
   195→): ClosedTabSnapshot[] {
   196→  if (snapshots.length === 0) {
   197→    return stack;
   198→  }
   199→
   200→  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
   201→}
   202→
   203→function restoreClosedTabIntoTabs(
   204→  tabs: PageTab[],
   205→  snapshot: ClosedTabSnapshot
   206→): { tabs: PageTab[]; restoredTab: PageTab } {
   207→  const restoredTab = cloneTabWithNewId(snapshot.tab);
   208→  const nextTabs = [...tabs];
   209→  const insertIndex = Math.max(0, Math.min(snapshot.originIndex, nextTabs.length));
   210→  nextTabs.splice(insertIndex, 0, restoredTab);
   211→  return { tabs: nextTabs, restoredTab };
   212→}
