   238→    icon: leaf?.icon,
   239→    descriptorId: leaf?.pattern,
   240→    meta: leaf?.meta,
   241→    url,
   242→  };
   243→}
   244→
   245→function findHistoryEntryByUrlInHistory(
   246→  navigationHistory: TabNavigationState[],
   247→  historyIndex: number,
   248→  url: string
   249→): number {
   250→  for (let index = historyIndex - 1; index >= 0; index -= 1) {
   251→    if (navigationHistory[index].url === url) {
   252→      return index;
   253→    }
   254→  }
   255→  return -1;
   256→}
   257→
   258→// ─── Persist Migration ───────────────────────────────────────────────────────
   259→
   260→interface LegacyTabNavigationState {
   261→  location: DesktopLocation;
   262→  breadcrumbStack: Array<{
   263→    id: string;
   264→    label: string;
   265→    icon?: unknown;
   266→    descriptorId?: string;
   267→    sourceNodeId?: string;
   268→    parentNodeId?: string;
   269→    target?: {
   270→      key: string;
   271→      location: DesktopLocation;
   272→      canonicalUrl: string;
   273→    };
   274→    meta?: Record<string, unknown>;
   275→  }>;
   276→  activeNodeId?: string;
   277→  activeIndexPath?: string[];
   278→}
   279→
   280→function migrateLegacyNavigationState(legacy: LegacyTabNavigationState): TabNavigationState | null {
   281→  // Convert location to URL
   282→  let url: string;
   283→  try {
   284→    url = locationToUrl(legacy.location);
   285→  } catch {
   286→    return null;
   287→  }
   288→
   289→  // Validate URL is known in registry
   290→  if (!registry.match(url)) {
   291→    return null;
   292→  }
   293→
   294→  // Convert breadcrumb stack items (extract href from target, use new format)
   295→  const breadcrumbStack: BreadcrumbStackItem[] = legacy.breadcrumbStack.map((item) => {
   296→    const result: BreadcrumbStackItem = {
   297→      id: item.id,
   298→      label: item.label,
   299→      icon: item.icon as BreadcrumbStackItem["icon"],
   300→      href: item.target?.canonicalUrl,
   301→      sourceNodeId: item.sourceNodeId,
   302→      parentNodeId: item.parentNodeId,
   303→      meta: item.meta as BreadcrumbStackItem["meta"],
   304→    };
   305→    return result;
   306→  });
   307→
   308→  return {
   309→    url,
   310→    breadcrumbStack,
   311→    activeNodeId: legacy.activeNodeId,
   312→    activeIndexPath: legacy.activeIndexPath,
   313→  };
   314→}
   315→
   316→function isLegacyNavigationState(value: unknown): value is LegacyTabNavigationState {
   317→  if (!value || typeof value !== "object") return false;
   318→  const candidate = value as Record<string, unknown>;
   319→  return (
   320→    candidate.location !== undefined &&
   321→    typeof candidate.location === "object" &&
   322→    candidate.location !== null &&
   323→    "kind" in (candidate.location as object) &&
   324→    Array.isArray(candidate.breadcrumbStack)
   325→  );
   326→}
   327→
   328→function migratePersistedState(persisted: Record<string, unknown>): Record<string, unknown> {
   329→  const tabs = persisted.tabs;
   330→  if (!Array.isArray(tabs)) return persisted;
   331→
   332→  const migratedTabs = tabs.map((tab: unknown) => {
   333→    if (!tab || typeof tab !== "object") return tab;
   334→    const tabObj = tab as Record<string, unknown>;
   335→    const history = tabObj.navigationHistory;
   336→    if (!Array.isArray(history)) return tab;
   337→
   338→    const migratedHistory: TabNavigationState[] = [];
   339→    for (const entry of history) {
   340→      // Already in new format
   341→      if (isNavigationState(entry)) {
   342→        migratedHistory.push(entry as TabNavigationState);
   343→        continue;
   344→      }
   345→      // Legacy format
   346→      if (isLegacyNavigationState(entry)) {
   347→        const migrated = migrateLegacyNavigationState(entry);
   348→        if (migrated) {
   349→          migratedHistory.push(migrated);
   350→        }
   351→        // If migration returns null (invalid/unrecognized URL), drop the entry
   352→        continue;
   353→      }
   354→      // Unknown format, drop
   355→    }
   356→
   357→    // Ensure at least one valid entry
   358→    const safeHistory = migratedHistory.length > 0
   359→      ? migratedHistory
   360→      : [buildStateFromUrl("/workspace")];
   361→
   362→    // Clamp historyIndex
   363→    const oldIndex = typeof tabObj.historyIndex === "number" ? tabObj.historyIndex : safeHistory.length - 1;
   364→    const historyIndex = Math.min(Math.max(oldIndex, 0), safeHistory.length - 1);
   365→
   366→    return {
   367→      ...tabObj,
   368→      navigationHistory: safeHistory,
   369→      historyIndex,
   370→    };
   371→  });
   372→
   373→  // Also migrate recentlyClosedTabs
   374→  const recentlyClosed = persisted.recentlyClosedTabs;
   375→  let migratedClosed = recentlyClosed;
   376→  if (Array.isArray(recentlyClosed)) {
   377→    migratedClosed = recentlyClosed.map((snapshot: unknown) => {
   378→      if (!snapshot || typeof snapshot !== "object") return snapshot;
   379→      const snapObj = snapshot as Record<string, unknown>;
   380→      const tab = snapObj.tab;
   381→      if (!tab || typeof tab !== "object") return snapshot;
   382→      const tabObj = tab as Record<string, unknown>;
   383→      const history = tabObj.navigationHistory;
   384→      if (!Array.isArray(history)) return snapshot;
   385→
   386→      const migratedHistory: TabNavigationState[] = [];
   387→      for (const entry of history) {
   388→        if (isNavigationState(entry)) {
   389→          migratedHistory.push(entry as TabNavigationState);
   390→          continue;
   391→        }
   392→        if (isLegacyNavigationState(entry)) {
   393→          const migrated = migrateLegacyNavigationState(entry);
   394→          if (migrated) {
   395→            migratedHistory.push(migrated);
   396→          }
   397→          continue;
   398→        }
   399→      }
   400→
   401→      const safeHistory = migratedHistory.length > 0
   402→        ? migratedHistory
   403→        : [buildStateFromUrl("/workspace")];
   404→
   405→      const oldIndex = typeof tabObj.historyIndex === "number" ? tabObj.historyIndex : safeHistory.length - 1;
   406→      const historyIndex = Math.min(Math.max(oldIndex, 0), safeHistory.length - 1);
   407→
   408→      return {
   409→        ...snapObj,
   410→        tab: {
   411→          ...tabObj,
   412→          navigationHistory: safeHistory,
   413→          historyIndex,
   414→        },
   415→      };
   416→    });
   417→  }
   418→
   419→  return {
   420→    ...persisted,
   421→    tabs: migratedTabs,
   422→    recentlyClosedTabs: migratedClosed,
   423→  };
   424→}
   425→
   426→// ─── Store ───────────────────────────────────────────────────────────────────
   427→
   428→export const useTabStore = create<TabState & TabActions>()(
   429→  persist(
   430→    (set, get) => ({
   431→      tabs: [],
   432→      activeTabId: null,
   433→      recentlyClosedTabs: [],
   434→
   435→      openTab: (tabData) => {
   436→        const id = generateTabId();
   437→        const newTab = normalizeTab({
   438→          id,
   439→          pinned: tabData.pinned ?? false,
   440→          navigationHistory: [tabData.navigationState],
   441→          historyIndex: 0,
   442→          viewMode: tabData.viewMode,
   443→        });
   444→
   445→        set((state) => ({
   446→          tabs: [...state.tabs, newTab],
   447→          activeTabId: id,
   448→        }));
   449→
   450→        return id;
   451→      },
   452→
   453→      closeTab: (tabId) => {
   454→        set((state) => {
   455→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   456→          if (tabIndex === -1) return state;
   457→
   458→          const recentlyClosedTabs = pushClosedSnapshots(
   459→            state.recentlyClosedTabs,
   460→            [createClosedSnapshot(state.tabs[tabIndex], tabIndex)]
   461→          );
   462→          const tabs = state.tabs.filter((tab) => tab.id !== tabId);
   463→          let activeTabId = state.activeTabId;
   464→
   465→          if (state.activeTabId === tabId) {
   466→            if (tabs.length === 0) {
   467→              activeTabId = null;
   468→            } else if (tabIndex >= tabs.length) {
   469→              activeTabId = tabs[tabs.length - 1].id;
   470→            } else {
   471→              activeTabId = tabs[tabIndex].id;
   472→            }
   473→          }
   474→
   475→          return { tabs, activeTabId, recentlyClosedTabs };
   476→        });
   477→      },
   478→
   479→      closeOtherTabs: (tabId) => {
   480→        set((state) => {
   481→          const snapshots = state.tabs
   482→            .map((tab, index) => ({ tab, index }))
   483→            .filter(({ tab }) => !tab.pinned && tab.id !== tabId)
   484→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   485→
   486→          return {
   487→            tabs: state.tabs.filter((tab) => tab.pinned || tab.id === tabId),
   488→            activeTabId: tabId,
   489→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   490→          };
   491→        });
   492→      },
   493→
   494→      closeTabsToRight: (tabId) => {
   495→        set((state) => {
   496→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   497→          if (tabIndex === -1) return state;
   498→
   499→          const snapshots = state.tabs
   500→            .map((tab, index) => ({ tab, index }))
   501→            .filter(({ tab, index }) => index > tabIndex && !tab.pinned)
   502→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   503→          const closingIds = new Set(snapshots.map((snapshot) => snapshot.tab.id));
   504→          const tabs = state.tabs.filter((tab) => !closingIds.has(tab.id));
   505→          const activeTabId = tabs.some((tab) => tab.id === state.activeTabId)
   506→            ? state.activeTabId
   507→            : tabId;
   508→
   509→          return {
   510→            tabs,
   511→            activeTabId,
   512→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   513→          };
   514→        });
   515→      },
   516→
   517→      setActiveTab: (tabId) => {
   518→        set({ activeTabId: tabId });
   519→      },
   520→
   521→      pinTab: (tabId) => {
   522→        set((state) => {
   523→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   524→          if (tabIndex === -1) return state;
   525→
   526→          const tab = state.tabs[tabIndex];
   527→          if (tab.pinned) return state;
   528→
   529→          const tabs = [...state.tabs];
   530→          tabs.splice(tabIndex, 1);
   531→
   532→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   533→          tabs.splice(insertIndex, 0, { ...tab, pinned: true });
   534→
   535→          return { tabs };
   536→        });
   537→      },
   538→
   539→      unpinTab: (tabId) => {
   540→        set((state) => {
   541→          const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   542→          if (tabIndex === -1) return state;
   543→
   544→          const tab = state.tabs[tabIndex];
   545→          if (!tab.pinned) return state;
   546→
   547→          const tabs = [...state.tabs];
   548→          tabs.splice(tabIndex, 1);
   549→
   550→          const insertIndex = findLastPinnedIndex(tabs) + 1;
   551→          tabs.splice(insertIndex, 0, { ...tab, pinned: false });
   552→
   553→          return { tabs };
   554→        });
   555→      },
   556→
   557→      setViewMode: (tabId, mode) => {
   558→        set((state) => ({
   559→          tabs: state.tabs.map((tab) =>
   560→            tab.id === tabId ? { ...tab, viewMode: mode } : tab
   561→          ),
   562→        }));
   563→      },
   564→
   565→      moveTab: (fromIndex, toIndex) => {
   566→        set((state) => {
   567→          if (
   568→            fromIndex === toIndex ||
   569→            fromIndex < 0 ||
   570→            toIndex < 0 ||
   571→            fromIndex >= state.tabs.length ||
   572→            toIndex >= state.tabs.length
   573→          ) {
   574→            return state;
   575→          }
   576→
   577→          const tabs = [...state.tabs];
   578→          const [moved] = tabs.splice(fromIndex, 1);
   579→          tabs.splice(toIndex, 0, moved);
   580→          return { tabs };
   581→        });
   582→      },
   583→
   584→      navigate: (tabId, url) => {
   585→        get().pushLocation(tabId, buildStateFromUrl(url));
   586→      },
   587→
   588→      pushNavigation: (tabId, url, leaf) => {
   589→        const tab = get().tabs.find((entry) => entry.id === tabId);
   590→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   591→        const currentStack = current?.breadcrumbStack ?? [];
   592→        const nextState: TabNavigationState = {
   593→          url,
   594→          breadcrumbStack: [...currentStack, leaf],
   595→        };
   596→        get().pushLocation(tabId, nextState);
   597→      },
   598→
   599→      replaceNavigation: (tabId, url, leaf) => {
   600→        const tab = get().tabs.find((entry) => entry.id === tabId);
   601→        const current = tab ? getTabCurrentState(normalizeTab(tab)) : null;
   602→        const currentStack = current?.breadcrumbStack ?? [];
   603→        const nextState: TabNavigationState = {
   604→          url,
   605→          breadcrumbStack: [...currentStack.slice(0, -1), leaf],
   606→        };
   607→        get().pushLocation(tabId, nextState);
   608→      },
   609→
   610→      resetNavigation: (tabId, url, stack) => {
   611→        const nextState: TabNavigationState = { url, breadcrumbStack: stack };
   612→        get().pushLocation(tabId, nextState);
   613→      },
   614→
   615→      replaceLocation: (tabId, next) => {
   616→        set((state) => ({
   617→          tabs: state.tabs.map((tab) => {
   618→            if (tab.id !== tabId) return tab;
   619→            const current = normalizeTab(tab);
   620→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex);
   621→            return normalizeTab({
   622→              ...current,
   623→              navigationHistory: [...baseHistory, next],
   624→              historyIndex: baseHistory.length,
   625→            });
   626→          }),
   627→        }));
   628→      },
   629→
   630→      pushLocation: (tabId, next) => {
   631→        set((state) => ({
   632→          tabs: state.tabs.map((tab) => {
   633→            if (tab.id !== tabId) return tab;
   634→            const current = normalizeTab(tab);
   635→            const baseHistory = current.navigationHistory.slice(0, current.historyIndex + 1);
   636→            return normalizeTab({
   637→              ...current,
   638→              navigationHistory: [...baseHistory, next],
   639→              historyIndex: baseHistory.length,
   640→            });
   641→          }),
   642→        }));
   643→      },
   644→
   645→      insertHistoryBeforeCurrent: (tabId, next) => {
   646→        set((state) => ({
   647→          tabs: state.tabs.map((tab) => {
   648→            if (tab.id !== tabId) return tab;
   649→            const current = normalizeTab(tab);
   650→            const before = current.navigationHistory.slice(0, current.historyIndex);
   651→            const fromCurrent = current.navigationHistory.slice(current.historyIndex);
   652→            return normalizeTab({
   653→              ...current,
   654→              navigationHistory: [...before, next, ...fromCurrent],
   655→              historyIndex: before.length,
   656→            });
   657→          }),
   658→        }));
   659→      },
   660→
   661→      jumpToHistory: (tabId, historyIndex) => {
   662→        set((state) => ({
   663→          tabs: state.tabs.map((tab) => {
   664→            if (tab.id !== tabId) return tab;
   665→            const current = normalizeTab(tab);
   666→            return normalizeTab({
   667→              ...current,
   668→              historyIndex,
   669→            });
   670→          }),
   671→        }));
   672→      },
   673→
   674→      goBack: (tabId) => {
   675→        set((state) => ({
   676→          tabs: state.tabs.map((tab) => {
   677→            if (tab.id !== tabId) return tab;
   678→            const current = normalizeTab(tab);
   679→            if (current.historyIndex <= 0) return current;
   680→            return {
   681→              ...current,
   682→              historyIndex: current.historyIndex - 1,
   683→            };
   684→          }),
   685→        }));
   686→      },
   687→
   688→      goForward: (tabId) => {
   689→        set((state) => ({
   690→          tabs: state.tabs.map((tab) => {
   691→            if (tab.id !== tabId) return tab;
   692→            const current = normalizeTab(tab);
   693→            if (current.historyIndex >= current.navigationHistory.length - 1) {
   694→              return current;
   695→            }
   696→            return {
   697→              ...current,
   698→              historyIndex: current.historyIndex + 1,
   699→            };
   700→          }),
   701→        }));
   702→      },
   703→
   704→      canGoBack: (tabId) => {
   705→        const tab = get().tabs.find((item) => item.id === tabId);
   706→        return tab ? normalizeTab(tab).historyIndex > 0 : false;
   707→      },
   708→
   709→      canGoForward: (tabId) => {
   710→        const tab = get().tabs.find((item) => item.id === tabId);
   711→        if (!tab) return false;
   712→        const current = normalizeTab(tab);
   713→        return current.historyIndex < current.navigationHistory.length - 1;
   714→      },
   715→
   716→      getCurrentUrl: (tabId) => {
   717→        const tab = get().tabs.find((item) => item.id === tabId);
   718→        if (!tab) return null;
   719→        const current = getTabCurrentState(normalizeTab(tab));
   720→        return current?.url ?? null;
   721→      },
   722→
   723→      getCurrentNavigationState: (tabId) => {
   724→        const tab = get().tabs.find((item) => item.id === tabId);
   725→        return tab ? getTabCurrentState(normalizeTab(tab)) : null;
   726→      },
   727→
   728→      findHistoryEntryByUrl: (tabId, url) => {
   729→        const tab = get().tabs.find((item) => item.id === tabId);
   730→        if (!tab) return -1;
   731→        const current = normalizeTab(tab);
   732→        return findHistoryEntryByUrlInHistory(
   733→          current.navigationHistory,
   734→          current.historyIndex,
   735→          url
   736→        );
   737→      },
   738→
   739→      closeAllTabs: () => {
   740→        set((state) => {
   741→          const snapshots = state.tabs
   742→            .map((tab, index) => ({ tab, index }))
   743→            .filter(({ tab }) => !tab.pinned)
   744→            .map(({ tab, index }) => createClosedSnapshot(tab, index));
   745→          const tabs = state.tabs.filter((tab) => tab.pinned);
   746→          return {
   747→            tabs,
   748→            activeTabId: tabs[0]?.id ?? null,
   749→            recentlyClosedTabs: pushClosedSnapshots(state.recentlyClosedTabs, snapshots),
   750→          };
   751→        });
   752→      },
   753→
   754→      duplicateTab: (tabId) => {
   755→        const state = get();
   756→        const tabIndex = state.tabs.findIndex((tab) => tab.id === tabId);
   757→        if (tabIndex === -1) return null;
   758→
   759→        const duplicatedTab = cloneTabWithNewId(state.tabs[tabIndex], {
   760→          pinned: false,
   761→        });
   762→
   763→        set((current) => {
   764→          const tabs = [...current.tabs];
   765→          tabs.splice(tabIndex + 1, 0, duplicatedTab);
   766→          return {
   767→            tabs,
   768→            activeTabId: duplicatedTab.id,
   769→          };
   770→        });
   771→
   772→        return duplicatedTab.id;
   773→      },
   774→
   775→      reopenClosedTab: () => {
   776→        let restoredTabId: string | null = null;
   777→
   778→        set((current) => {
   779→          const [nextSnapshot, ...restSnapshots] = current.recentlyClosedTabs;
   780→          if (!nextSnapshot) return current;
   781→
   782→          const restored = restoreClosedTabIntoTabs(current.tabs, nextSnapshot);
   783→          restoredTabId = restored.restoredTab.id;
   784→
   785→          return {
   786→            tabs: restored.tabs,
   787→            activeTabId: restored.restoredTab.id,
   788→            recentlyClosedTabs: restSnapshots,
   789→          };
   790→        });
   791→
   792→        return restoredTabId;
   793→      },
   794→
   795→      restoreTab: (tab) => {
   796→        const restoredTab = cloneTabWithNewId(tab);
   797→        set((state) => ({
   798→          tabs: [...state.tabs, restoredTab],
   799→          activeTabId: restoredTab.id,
   800→        }));
   801→      },
   802→    }),
   803→    {
   804→      name: TAB_STORE_STORAGE_KEY,
   805→      version: TAB_STORE_VERSION,
   806→      partialize: (state) => ({
   807→        tabs: state.tabs,
   808→        activeTabId: state.activeTabId,
   809→        recentlyClosedTabs: state.recentlyClosedTabs,
   810→      }),
   811→      migrate: (persisted, version) => {
   812→        if (version < TAB_STORE_VERSION) {
   813→          return migratePersistedState(persisted as Record<string, unknown>);
   814→        }
   815→        return persisted;
   816→      },
   817→      merge: (persisted, current) => {
   818→        return {
   819→          ...current,
   820→          ...mergePersistedTabState(
   821→            persisted as Partial<TabState> | undefined,
   822→            current
   823→          ),
   824→        };
   825→      },
   826→    }
   827→  )
   828→);
